Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=('f1f13ece5ffde3838deff4130bdd8b9a78e2497297ead167a7db6af46ab89fce',), event=Revised(decision='failuresaretodos', at=datetime(2026, 11, 20, 0, 0, 0), actor='assistant', title='A persistent failure files a todo on the upkeep chain, where an agent can fix it', body="A failure that persists (a red nightly gate, a public push that door 2 refused, a mail account failing for more than a day) files a todo on the chain `[upkeep] chain` names, once per failure episode, priced by its class: the todo's id is a function of the failure, so asking again adds nothing. An instance with no `[upkeep]` files none. The nightly gate and the public push write the todo; a mail account's failure is proposed as a card, and the owner's tap writes it. A card is kept only for what the owner alone can do, such as a sign-in or a consent, and the todo names the card. The two are different audiences, not duplicates.", rationale="The owner, 2026-10-25: the todo should be on the project's own chain, so an agent can fix it and pick up the most important tasks first. Restated 2026-11-20: that chain is the one `[upkeep] chain` names, not a fixed name.", supersedes=()))